CREATE TABLE channels (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  kind text NOT NULL CHECK (kind IN ('project','task','group','direct')),
  container_id uuid /* id -> hierarchy.containers */,              -- project-wise messaging
  task_id uuid /* id -> tasks.tasks */,
  name text, is_private boolean NOT NULL DEFAULT false,
  created_by uuid /* id -> identity.users */, archived_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1,
  CHECK ((kind = 'project') = (container_id IS NOT NULL)),
  CHECK ((kind = 'task') = (task_id IS NOT NULL))
);

CREATE UNIQUE INDEX channels_project_uk ON channels (container_id) WHERE kind = 'project' AND archived_at IS NULL;

CREATE TABLE channel_members (
  channel_id uuid NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  user_id uuid NOT NULL /* id -> identity.users */,
  last_read_seq bigint NOT NULL DEFAULT 0, muted boolean NOT NULL DEFAULT false,
  PRIMARY KEY (channel_id, user_id)
);

CREATE TABLE messages (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  id uuid NOT NULL,
  channel_id uuid NOT NULL REFERENCES channels(id),
  seq bigint GENERATED ALWAYS AS IDENTITY,                  -- read cursor per channel
  author_id uuid /* id -> identity.users */,
  parent_id uuid,                                           -- thread root
  body text NOT NULL, attachments jsonb NOT NULL DEFAULT '[]',
  edited_at timestamptz, deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, id)
) PARTITION BY HASH (workspace_id);

